package cn.huankan.event;
import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/watch")public class WatchController {private final WatchService s;public WatchController(WatchService service){s=service;}public record Page(int page){}public record Remove(UUID id){}@PostMapping("/query")public Object query(@RequestHeader("Authorization")String auth){return s.list(WatchService.owner(auth));}@PostMapping("/catalog")public Object catalog(){return s.catalog();}@PostMapping("/add")public Object add(@RequestHeader("Authorization")String auth,@RequestBody WatchService.Add q){return s.add(WatchService.owner(auth),q);}@PostMapping("/remove")public Object remove(@RequestHeader("Authorization")String auth,@RequestBody Remove q){return s.remove(WatchService.owner(auth),q.id());}@PostMapping("/radar")public Object radar(@RequestHeader("Authorization")String auth,@RequestBody Page q){return s.radar(WatchService.owner(auth),q.page());}@ExceptionHandler({IllegalArgumentException.class,org.springframework.dao.DataAccessException.class})public org.springframework.http.ResponseEntity<?> invalid(){return org.springframework.http.ResponseEntity.badRequest().body(Map.of("message","关注条件无效或目标尚无真实目录证据"));}}
